mapper.insert:
INSERT INTO enterprise_configuration_snapshot (
    snapshot_id, revision, digest, schema_version, document_json,
    etag, active, generated_at, inserted_at
) VALUES (
    #{snapshotId}, #{revision}, #{digest}, #{schemaVersion}, #{documentJson},
    #{etag}, #{active}, #{generatedAt}, #{insertedAt}
)
ON CONFLICT (snapshot_id, revision) DO NOTHING

mapper.select:
SELECT *
FROM enterprise_configuration_snapshot
WHERE snapshot_id = #{snapshotId}
  AND revision = #{revision}

mapper.insert:
INSERT INTO enterprise_package_document (
    package_id, kind, revision, digest, document_json, inserted_at
) VALUES (
    #{packageId}, #{kind}, #{revision}, #{digest}, #{documentJson}, #{insertedAt}
)
ON CONFLICT (package_id, revision) DO NOTHING

mapper.select:
SELECT *
FROM enterprise_package_document
WHERE package_id = #{packageId}
  AND revision = #{revision}
